CREATE INDEX "IX_Comments_RequestId" ON "Comments" ("RequestId");

CREATE INDEX "IX_AuditEntries_RequestId" ON "AuditEntries" ("RequestId");

CREATE INDEX "IX_Requests_CategoryId" ON "Requests" ("CategoryId");

CREATE INDEX "IX_StatusHistories_RequestId" ON "StatusHistories" ("RequestId");

SELECT setval(
    pg_get_serial_sequence('"Categories"', 'Id'),
    GREATEST(
        (SELECT MAX("Id") FROM "Categories") + 1,
        nextval(pg_get_serial_sequence('"Categories"', 'Id'))),
    false);

SELECT setval(
    pg_get_serial_sequence('"Requests"', 'Id'),
    GREATEST(
        (SELECT MAX("Id") FROM "Requests") + 1,
        nextval(pg_get_serial_sequence('"Requests"', 'Id'))),
    false);

SELECT setval(
    pg_get_serial_sequence('"Comments"', 'Id'),
    GREATEST(
        (SELECT MAX("Id") FROM "Comments") + 1,
        nextval(pg_get_serial_sequence('"Comments"', 'Id'))),
    false);

